import "./StreakBadge.css";
import type { ReactElement } from "react";

export interface StreakBadgeProps {
  /** The current day of the streak, counted from 1. */
  day: number;
  /** The length of the full streak, such as 66. */
  total: number;
}

export function StreakBadge({ day, total }: StreakBadgeProps): ReactElement {
  const safeTotal = Math.max(1, Math.floor(total));
  const current = Math.min(Math.max(Math.round(day), 0), safeTotal);
  const percent = Math.round((current / safeTotal) * 100);
  const text = `Day ${current} of ${safeTotal}`;

  return (
    <div className="streak-badge">
      <span className="streak-badge__label">{text}</span>
      <div
        className="streak-badge__track"
        role="progressbar"
        aria-label="Streak progress"
        aria-valuemin={0}
        aria-valuemax={safeTotal}
        aria-valuenow={current}
        aria-valuetext={text}
      >
        <span className="streak-badge__fill" style={{ width: `${percent}%` }} />
      </div>
    </div>
  );
}
```

