.streak-badge {
  display: inline-flex;
  align-items: center;
  gap: clamp(0.5rem, 1.2vw, 0.75rem);
  padding: 0.4em 1em 0.4em 0.9em;
  border-radius: 999px;
  border: 1px solid var(--hair);
  background: var(--myelin-wash);
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.8rem, 1.1vw, 0.95rem);
  line-height: 1.2;
}

.streak-badge__label {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.streak-badge__track {
  position: relative;
  overflow: hidden;
  flex: 0 0 auto;
  width: clamp(4rem, 12vw, 8rem);
  height: 0.375rem;
  border-radius: 999px;
  background: var(--axon-ahead);
}

.streak-badge__fill {
  position: absolute;
  inset: 0 auto 0 0;
  max-width: 100%;
  border-radius: 999px;
  background: var(--myelin);
  transition: width 400ms ease-out;
}

:root[data-motion="reduce"] .streak-badge__fill {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .streak-badge__fill {
    transition: none;
  }
}
